#include<bits/stdc++.h>

using namespace std;

int main(){
  string s,t;
  cin >> s >> t;
  int sl=s.size(),tl=t.size();
  if(sl<tl){
    cout << "No\n";
    return 0;
  }
  vector<string> s_sub;
  for(int i=0;i<sl-tl+1;i++){
    string cur;
    for(int j=0;j<tl;j++){
      cur.push_back(s[i+j]);
    }
    s_sub.push_back(cur);
  }
  for(auto &nx : s_sub){
    if(nx==t){
      cout << "Yes\n";
      return 0;
    }
  }
  cout << "No\n";
  return 0;
}

